cat > /tmp/decode.js <<'EOF'
const fs=require('fs'), zlib=require('zlib');
function decode(file){
  const b=fs.readFileSync(file);
  let pos=8, w,h,ct,bd, idat=[];
  while(pos<b.length){
    const len=b.readUInt32BE(pos); const type=b.toString('ascii',pos+4,pos+8);
    const data=b.subarray(pos+8,pos+8+len);
    if(type==='IHDR'){w=data.readUInt32BE(0);h=data.readUInt32BE(4);bd=data[8];ct=data[9];}
    if(type==='IDAT') idat.push(data);
    if(type==='IEND') break;
    pos+=12+len;
  }
  const raw=zlib.inflateSync(Buffer.concat(idat));
  const ch = ct===2?3: ct===6?4: ct===0?1:3;
  const stride=w*ch;
  const out=Buffer.alloc(h*stride);
  let p=0;
  for(let y=0;y<h;y++){
    const f=raw[p++]; const line=raw.subarray(p,p+stride); p+=stride;
    const prev = y>0? out.subarray((y-1)*stride,y*stride):Buffer.alloc(stride);
    const cur=out.subarray(y*stride,(y+1)*stride);
    for(let x=0;x<stride;x++){
      const a = x>=ch? cur[x-ch]:0, bb=prev[x], c=x>=ch?prev[x-ch]:0;
      let v=line[x];
      if(f===1) v+=a; else if(f===2) v+=bb; else if(f===3) v+=((a+bb)>>1);
      else if(f===4){const pa=Math.abs(bb-c),pb=Math.abs(a-c),pc=Math.abs(a+bb-2*c);v+= (pa<=pb&&pa<=pc)?a:(pb<=pc?bb:c);}
      cur[x]=v&255;
    }
  }
  return {w,h,ch,data:out};
}
const img=decode(process.argv[2]);
const y0=+process.argv[3], y1=+process.argv[4];
const {w,h,ch,data}=img;
function isBg(x,y){const i=(y*w+x)*ch;const r=data[i],g=data[i+1],bl=data[i+2];return r>245&&g>245&&bl>245;}
// column occupancy: count non-bg pixels in band
const occ=new Array(w).fill(0);
for(let y=y0;y<y1;y++) for(let x=0;x<w;x++) if(!isBg(x,y)) occ[x]++;
let runs=[],start=-1;
for(let x=0;x<w;x++){
  if(occ[x]>0&&start<0)start=x;
  if((occ[x]===0)&&start>=0){runs.push([start,x-1]);start=-1;}
}
if(start>=0)runs.push([start,w-1]);
console.log('width',w,'band',y0,y1);
console.log('runs',runs.filter(r=>r[1]-r[0]>5).map(r=>r[0]+'-'+r[1]+' w='+(r[1]-r[0]+1)));
EOF
